const $=s=>document.querySelector(s);const solutions=[
{slug:'agriculture',title:'Agriculture & crops',tag:'Grow with greater clarity',image:'agriculture.jpg',desc:'See beyond the field. Understand crop conditions and identify where attention is needed.',headline:'Every field tells a story. See the whole picture.',intro:'Turn satellite observations into a clearer understanding of crop development, seasonal patterns, and areas that need a closer look.',items:['Field-level vegetation indicators','Seasonal growth and historical comparisons','Within-field variability and inspection priorities'],outputs:['Crop condition maps','Seasonal trend charts','Field summary reports'],method:'optical',limit:'Vegetation indicators reveal changes in crop condition, not a definitive cause. Cloud cover, crop stage, resolution, and field observations affect interpretation.'},
{slug:'buildings',title:'Buildings & urban areas',tag:'Understand the ground beneath',image:'buildings.jpg',desc:'Track ground movement around buildings and urban assets over time.',headline:'A different perspective on the ground beneath your assets.',intro:'Observe movement patterns around buildings and urban areas to support investigation, maintenance, and asset planning.',items:['Historical ground displacement assessment','Movement trends around asset portfolios','Locations for further engineering investigation'],outputs:['Displacement maps','Point-level time series','Analyst-reviewed summaries'],method:'radar',limit:'InSAR measures relative displacement along the satellite line of sight. It does not directly certify structural safety or reveal every building defect.'},
{slug:'mining',title:'Mining & volumes',tag:'Measure a changing landscape',image:'mining.jpg',desc:'Measure terrain change, estimate volumes, and observe movement across mining sites.',headline:'Make sense of a landscape that never stands still.',intro:'Combine suitable elevation data and satellite observations to understand material change and ground movement across mining operations.',items:['Stockpile and terrain volume estimation','Excavation and deposition comparison','Movement around suitable mine infrastructure'],outputs:['Surface difference maps','Volume change summaries','Ground movement reports'],method:'volume',limit:'Volume calculations require suitable elevation data, boundaries, and a reference surface. Radar displacement maps alone do not provide stockpile volumes.'},
{slug:'dams',title:'Dams & embankments',tag:'An additional layer of insight',image:'dams.jpg',desc:'Add surface movement intelligence to established dam inspection programs.',headline:'More context for the assets that hold so much.',intro:'Observe measurable surface movement around dams, embankments, and surrounding terrain to complement engineering assessments.',items:['Historical surface displacement','Surrounding slope and terrain monitoring','Changes requiring specialist review'],outputs:['Measurement quality maps','Displacement time series','Review-ready findings'],method:'radar',limit:'Satellite analysis supports established inspection and instrumentation programs. It does not guarantee failure prediction or provide continuous emergency surveillance.'},
{slug:'bridges',title:'Bridges & structures',tag:'Connect observations to action',image:'bridges.jpg',desc:'Explore movement patterns around bridges, approaches, and surrounding terrain.',headline:'A wider view of your critical connections.',intro:'Assess the suitability of satellite observations for tracking ground movement around transport structures and their approaches.',items:['Bridge approach and surrounding ground movement','Historical displacement assessment','Portfolio screening for further investigation'],outputs:['Asset-area maps','Displacement trends','Feasibility assessments'],method:'radar',limit:'Suitability depends on observation geometry and available measurement points. Repeat-pass satellite analysis does not provide live vibration or traffic-load measurements.'},
{slug:'roads',title:'Roads & rail corridors',tag:'See the length of the challenge',image:'roads.jpg',desc:'Identify changing ground conditions along roads, rail lines, and embankments.',headline:'Long corridors. A connected understanding.',intro:'Screen transport corridors for ground movement patterns and focus inspection efforts on locations that merit closer attention.',items:['Corridor-scale movement screening','Segment-based comparisons','Embankment and adjacent slope assessment'],outputs:['Segment-level maps','Historical trend summaries','Inspection priority reports'],method:'radar',limit:'Observation density and quality vary along a corridor. Missing measurements must not be interpreted as an absence of movement.'}];
const methods={optical:{name:'Optical remote sensing',steps:['Observe','Compare','Understand'],text:['Sunlight reflects from crops. Satellites record different spectral bands to describe the surface.','Compare suitable observations across dates to understand vegetation patterns and seasonal change.','Vegetation indicators highlight areas for field inspection. They do not establish the cause of stress.']},radar:{name:'Radar & InSAR',steps:['Observe','Measure','Interpret'],text:['A radar satellite transmits microwave signals and records their return from suitable surface targets.','Compare the phase of repeated observations to estimate relative displacement along the satellite line of sight.','Review displacement trends, reference points, and quality indicators before deciding where to investigate.']},volume:{name:'Elevation & volume analysis',steps:['Map','Difference','Quantify'],text:['Build or obtain suitable dated elevation surfaces for a clearly defined site boundary.','Compare the surfaces against a consistent reference to identify excavation and deposition.','Calculate estimated volume change with units, source dates, and uncertainty recorded.']}};
const arrow='↗';const cta=()=>`<section class="cta"><div><div class="eyebrow">Your site. Your questions. Our perspective.</div><h2>Let’s see what’s possible.</h2><p>Start with a conversation. We’ll assess the right approach for your site.</p></div><a class="button dark" href="#/contact">Discuss your project ${arrow}</a></section>`;
function cards(){return `<div class="cards">${solutions.map((s,i)=>`<a class="solution-card" href="#/solutions/${s.slug}"><div class="card-img"><img src="${s.image}" alt="${s.title}" loading="lazy"><span class="card-number">0${i+1} / ${s.slug.toUpperCase()}</span></div><div class="card-content"><h3>${s.title}</h3><p>${s.desc}</p><div class="card-bottom"><span>Explore solution</span><span>${arrow}</span></div></div></a>`).join('')}</div>`}
function art(method='radar',step=0){const colors=['#d5f56b','#93c8ac','#e5c96e'];return `<svg viewBox="0 0 540 320" role="img" aria-label="Conceptual ${methods[method].name} illustration, step ${step+1}"><defs><pattern id="grid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M 30 0 L 0 0 0 30" fill="none" stroke="#829f9620"/></pattern><linearGradient id="beam" x2="0" y2="1"><stop stop-color="#d5f56b" stop-opacity=".5"/><stop offset="1" stop-color="#d5f56b" stop-opacity="0"/></linearGradient></defs><rect width="540" height="320" fill="url(#grid)"/><path d="M55 225 250 150 488 225 285 302Z" fill="#284d47" stroke="#87a38b"/><path d="M55 225 285 302 285 315 55 238Z" fill="#1a3e3d"/><path d="M285 302 488 225 488 239 285 315Z" fill="#203c36"/>${Array.from({length:7},(_,i)=>`<path d="M${80+i*25} ${215-i*9} L${307+i*25} ${292-i*9}" stroke="#a0bc7540"/>`).join('')}${method==='volume'?`<path d="M155 235 245 162 345 243 260 274Z" fill="#a6b67988" stroke="#d5f56b"/><path d="M155 235 245 ${180-step*10} 345 243" fill="none" stroke="white" stroke-dasharray="5 5"/>`:`<path class="scan" d="M260 65 140 246 375 246Z" fill="url(#beam)"/><g transform="translate(245,45) rotate(-20)"><rect x="-35" y="0" width="25" height="18" fill="#749990" stroke="#c6dbcb"/><rect x="17" y="0" width="25" height="18" fill="#749990" stroke="#c6dbcb"/><rect x="-6" y="-5" width="20" height="27" fill="#dde4cf"/><path d="M2 23 0 35 10 35Z" fill="#d5f56b"/></g>`}${Array.from({length:12},(_,i)=>`<circle cx="${160+(i%4)*48}" cy="${210+Math.floor(i/4)*22-(i%4)*5}" r="${step===0?3:5}" fill="${colors[(i+step)%3]}" opacity=".85"/>`).join('')}<text x="25" y="28" fill="#bcd0c7" font-size="10" font-family="monospace">${methods[method].name.toUpperCase()} / 0${step+1}</text><text x="370" y="105" fill="#d5f56b" font-size="11" font-family="monospace">${step===0?'OBSERVATION':step===1?'CHANGE ANALYSIS':'ACTIONABLE CONTEXT'}</text><path d="M370 115 335 145" stroke="#8ba786" fill="none"/></svg>`}
function explainer(method){return `<div class="explainer paused" data-method="${method}"><div class="science-art">${art(method)}<span class="caption">CONCEPTUAL ILLUSTRATION · MOVEMENT EXAGGERATED</span></div><div class="animation-controls">${methods[method].steps.map((s,i)=>`<button data-step="${i}" class="${i===0?'active':''}">0${i+1} ${s}</button>`).join('')}<button data-play aria-label="Play explanation">Play ▷</button></div><p class="animation-description">${methods[method].text[0]}</p></div>`}
function home(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">Earth intelligence. Human impact.</div><h1>A clearer view.<br>A better <em>decision.</em></h1><p>From the crops we grow to the infrastructure we depend on. See what’s changing with satellite intelligence from ZARBITZ.</p><div class="hero-actions"><a class="button" href="#/solutions">Explore our solutions ${arrow}</a><a class="text-link" href="#/technology">Discover the science ↗</a></div><p class="hero-note">OBSERVE THE EARTH. UNDERSTAND THE CHANGE.</p></div><div class="earth-wrap" aria-label="Conceptual Earth observation visual"><div class="earth"></div><div class="orbital"></div><div class="cross">+</div><div class="signal"></div><div class="map-tag one"><b>GROUND MOVEMENT</b>A new perspective on stability<small>RADAR / TIME-SERIES ANALYSIS</small></div><div class="map-tag two"><b>CROP INTELLIGENCE</b>Insight across every season<small>OPTICAL / VEGETATION INDICATORS</small></div><span class="map-caption">EARTH OBSERVATION · CONCEPTUAL VISUAL</span></div></section><div class="strip"><span>A wider perspective. A practical purpose.</span><b>◎ &nbsp; Satellite observation</b><b>⌁ &nbsp; Scientific analysis</b><b>↗ &nbsp; Informed decisions</b></div><section class="section"><div class="eyebrow">Our solutions</div><div class="section-head"><h2>One planet.<br>Many possibilities.</h2><p>Understand change across the places that matter to you. Purpose-built insights for land, livelihoods, and infrastructure.</p></div>${cards()}</section><section class="section science"><div><div class="eyebrow">The science, made clear</div><h2>From a signal in space<br>to insight on the ground.</h2><p>Satellites see the Earth differently. We translate optical, radar, and elevation observations into a perspective you can understand and use.</p><a class="text-link" href="#/technology">See how our technology works ↗</a></div><div>${explainer('radar')}</div></section><section class="section"><div class="eyebrow">How we work</div><h2>A clear path from question to insight.</h2><div class="steps">${[['Define your area','Tell us about your site, assets, and the questions you need to answer.'],['Assess feasibility','We evaluate available observations and the right scientific approach.'],['Analyze the change','Suitable data is processed, checked, and reviewed in context.'],['Put insight to work','Explore approved maps, reports, and datasets in your workspace.']].map((s,i)=>`<div class="step"><span>0${i+1} /</span><h3>${s[0]}</h3><p>${s[1]}</p></div>`).join('')}</div></section>${cta()}`}
function detail(s){return `<section class="detail-hero"><div class="page-intro"><div class="eyebrow">Solutions / ${s.title}</div><h1>${s.headline}</h1><p>${s.intro}</p><a class="button" href="#/contact?solution=${s.slug}">Discuss your project ↗</a></div><img class="detail-image" src="${s.image}" alt="${s.title}"></section><section class="section two-col"><div><div class="eyebrow">${s.tag}</div><h2>Observe the change.<br>Understand the context.</h2><p>${s.desc}</p></div><div>${s.items.map((x,i)=>`<div class="list-row"><span>0${i+1}</span><p>${x}</p></div>`).join('')}</div></section><section class="section science"><div><div class="eyebrow">Behind the insight</div><h2>The science,<br>step by step.</h2><p>Explore how ${methods[s.method].name.toLowerCase()} turns suitable observations into useful information.</p><div class="notice">${s.limit}</div></div>${explainer(s.method)}</section><section class="section"><div class="eyebrow">What you receive</div><h2>Information you can work with.</h2><div class="steps" style="grid-template-columns:repeat(auto-fit,minmax(200px,1fr))">${s.outputs.map((x,i)=>`<div class="step"><span>0${i+1} / DELIVERABLE</span><h3>${x}</h3><p>Delivered with observation dates, methodology, quality information, and relevant limitations.</p></div>`).join('')}</div><p class="fine">Coverage, resolution, update frequency, and delivery timelines are agreed after a project-specific feasibility assessment.</p></section><section class="section faq"><div class="eyebrow">Common questions</div><h2>A little more clarity.</h2><details><summary>Can you monitor my site?</summary><p>We first assess the location, asset characteristics, available data, and required outputs. Monitoring suitability is confirmed before a project is agreed.</p></details><details><summary>How often will I receive updates?</summary><p>The schedule depends on suitable satellite acquisitions, processing, and analyst review. We agree observation and delivery expectations for each project.</p></details><details><summary>Who can access my results?</summary><p>The planned customer platform uses administrator-approved project, report, and dataset permissions. This website currently includes an illustrative workspace demo.</p></details></section>${cta()}`}
function technology(){return `<section class="page-intro"><div class="eyebrow">Our technology</div><h1>Understand the science.<br>Trust the perspective.</h1><p>Different questions call for different observations. Explore three complementary ways to understand a changing Earth.</p></section>${Object.keys(methods).map((m,i)=>`<section class="section science" style="background:${i%2?'#f7f8f2':'#e9eee3'}"><div><div class="eyebrow">0${i+1} / Measurement to meaning</div><h2>${methods[m].name}</h2><p>${methods[m].text.join(' ')}</p><a class="text-link" href="#/solutions">Find your application ↗</a></div>${explainer(m)}</section>`).join('')}<section class="section"><div class="eyebrow">Built on scientific context</div><h2>A result is only useful<br>when you understand its limits.</h2><div class="steps">${['Source & observation dates','Method & reference system','Quality & uncertainty','Interpretation & next steps'].map((x,i)=>`<div class="step"><span>0${i+1}</span><h3>${x}</h3><p>Essential context accompanies each agreed project deliverable.</p></div>`).join('')}</div></section>${cta()}`}
function contact(){return `<section class="page-intro"><div class="eyebrow">Let’s start a conversation</div><h1>What would you like<br>to see more clearly?</h1><p>Tell us about your location, your assets, and your questions.</p></section><section class="form-layout"><div><h3>Your project starts with a question.</h3><p>From a single field to an infrastructure portfolio, the first step is understanding what you need to monitor.</p><div class="list-row"><span>01</span><p>Share your area and objectives</p></div><div class="list-row"><span>02</span><p>Explore suitable observations</p></div><div class="list-row"><span>03</span><p>Define a practical monitoring scope</p></div><div class="notice">Design preview: enquiry delivery is not connected yet. You can prepare and download your enquiry here; no message will be sent.</div></div><form class="form-card" id="contact-form"><div class="fields"><div><label for="name">Full name *</label><input id="name" name="name" required autocomplete="name"></div><div><label for="email">Email address *</label><input id="email" name="email" type="email" required autocomplete="email"></div><div><label for="organization">Organization</label><input id="organization" name="organization" autocomplete="organization"></div><div><label for="phone">Phone number (optional)</label><input id="phone" name="phone" type="tel" autocomplete="tel"></div><div class="full"><label for="solution">I’m interested in</label><select id="solution" name="solution">${solutions.map(s=>`<option value="${s.slug}">${s.title}</option>`).join('')}<option>Enterprise access</option><option>Partnerships</option></select></div><div class="full"><label for="location">Site location / country *</label><input id="location" name="location" required></div><div class="full"><label for="message">Tell us about your project *</label><textarea id="message" name="message" required placeholder="What would you like to monitor? Include approximate area, number of assets, and your objectives."></textarea></div></div><p class="fine">Your draft stays in this page and is not transmitted. Please avoid confidential information.</p><button class="button dark" type="submit">Download enquiry draft ↓</button><p id="form-result" class="result" role="status"></p></form></section>`}
let authType='individual',authMode='signin';function auth(){return `<section class="auth"><div class="eyebrow">ZARBITZ workspace</div><h1>${authMode==='signup'?'Create your account':'Welcome to a clearer view.'}</h1><p class="fine">${authMode==='signup'?'Registration is followed by administrator approval.':'Your projects, reports, and data. In one place.'}</p><div class="tabs"><button class="tab ${authType==='individual'?'active':''}" data-auth="individual">Individual</button><button class="tab ${authType==='enterprise'?'active':''}" data-auth="enterprise">Enterprise</button></div><div class="notice">Authentication setup pending. Google sign-in, email, phone verification, and authenticator MFA will be connected later. This preview does not collect credentials.</div><button class="button outline" data-info="google">G &nbsp; Continue with Google <span>↗</span></button><button class="button outline" data-info="email">Continue with email <span>↗</span></button><button class="button outline" data-info="phone">Continue with phone <span>↗</span></button>${authType==='enterprise'?'<button class="button outline" data-info="sso">Enterprise SSO <span>↗</span></button>':''}<p class="fine">Authenticator-app verification is a second step, separate from Google sign-in.</p><a class="button dark" href="#/workspace">Explore the demo workspace ↗</a><p class="fine">${authMode==='signup'?'Already have an account? <a href="#/signin">Sign in</a>':'New to ZARBITZ? <a href="#/signup">Create an account ↗</a>'}</p></section>`}
const permissions={report:true,dataset:false};let portalTab='overview';function workspace(){return `<section class="portal"><div class="notice">Interactive design demo · All projects and measurements are fictional. Permissions affect this browser demo only and are not production security.</div><div class="portal-top"><div><div class="eyebrow" style="margin-top:30px">Demo organization / Fieldworks</div><h2>Your earth intelligence.</h2><span class="badge">3 illustrative projects</span></div><div class="tabs">${['overview','reports','datasets','admin'].map(x=>`<button class="tab ${portalTab===x?'active':''}" data-portal="${x}">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div></div>${portalTab==='overview'?`<div class="dashboard-grid"><div class="panel"><h3>Project areas</h3><div class="demo-map" role="img" aria-label="Illustrative project locations"><span class="marker" style="top:35%;left:30%"></span><span class="marker" style="top:60%;left:55%"></span><span class="marker" style="top:40%;left:75%"></span><div class="map-tag two" style="color:white">Illustrative locations · not a monitoring map</div></div><div class="metric"><b>North Fields · Agriculture</b><span>Report published</span></div><div class="metric"><b>Urban Portfolio · Ground movement</b><span>Under review</span></div><div class="metric"><b>West Quarry · Volume change</b><span>Awaiting data</span></div></div><div><div class="panel"><h3>Workspace activity</h3><div class="metric"><span>Crop conditions · v1.2</span><span class="badge">Published</span></div><p class="fine">Sample observation: 12 Oct 2026<br>Sample publication: 16 Oct 2026</p><button class="button dark" data-portal="reports">View reports ↗</button></div><div class="panel"><h3>Your access</h3><p class="fine">Reports: ${permissions.report?'Approved':'Not granted'}<br>Dataset downloads: ${permissions.dataset?'Approved':'Not granted'}</p><p class="fine">Use the Admin demo to explore independent permissions.</p></div></div></div>`:portalTab==='admin'?`<div class="panel"><h3>Access management</h3><p class="fine">Demo user: Alex Morgan · Fieldworks · Customer Viewer. No real users or private data.</p><div class="table-wrap"><table><thead><tr><th>Resource</th><th>Scope</th><th>Grant permission</th></tr></thead><tbody><tr><td>View published reports</td><td>North Fields only</td><td><input class="toggle" type="checkbox" aria-label="Grant report access" data-permission="report" ${permissions.report?'checked':''}></td></tr><tr><td>Download dataset</td><td>North Fields example CSV</td><td><input class="toggle" type="checkbox" aria-label="Grant dataset download" data-permission="dataset" ${permissions.dataset?'checked':''}></td></tr></tbody></table></div><p class="result" id="permission-status" role="status">Changes apply immediately within this demo.</p></div><div class="panel"><h3>Publication stages</h3><p>Draft → Technical review → Approved → Published</p><p class="fine">Production access must be enforced by the server for every project, preview, and download.</p></div>`:`<div class="panel"><h3>${portalTab==='reports'?'Published reports':'Project datasets'}</h3><div class="table-wrap"><table><thead><tr><th>Resource</th><th>Project</th><th>Status</th><th>Action</th></tr></thead><tbody><tr><td>${portalTab==='reports'?'Crop conditions · v1.2':'Vegetation indicators · CSV'}</td><td>North Fields</td><td>${permissions[portalTab==='reports'?'report':'dataset']?'Access approved':'Access not granted'}</td><td><button data-resource="${portalTab}">${permissions[portalTab==='reports'?'report':'dataset']?(portalTab==='reports'?'Open report':'Download example'):'Request access'}</button></td></tr></tbody></table></div><p class="fine">Illustrative data only. Dataset access and report access are separate permissions.</p><p id="request-status" role="status" class="result"></p></div>`}</section>`}
function about(){return `<section class="page-intro"><div class="eyebrow">About ZARBITZ</div><h1>A wider perspective.<br>A grounded purpose.</h1><p>We’re building ZARBITZ to make satellite observations useful to the people who care for land, grow food, and manage infrastructure.</p></section><section class="section science"><div><h2>Space technology.<br>Earth-level questions.</h2><p>Where are crop conditions changing? Which locations merit further inspection? How has a landscape changed over time?</p><p>Our approach connects those practical questions to suitable remote-sensing methods, transparent analysis, and understandable deliverables.</p></div><div class="science-art">${art('optical')}<span class="caption">A PERSPECTIVE WITH PURPOSE</span></div></section><section class="section"><div class="eyebrow">Our principles</div><div class="steps"><div class="step"><h3>Scientific clarity</h3><p>Explain what is measured, inferred, and uncertain.</p></div><div class="step"><h3>Practical relevance</h3><p>Start with the decision a customer needs to make.</p></div><div class="step"><h3>Responsible access</h3><p>Keep customer resources scoped to authorized users.</p></div><div class="step"><h3>Honest expectations</h3><p>Assess feasibility before promising results.</p></div></div></section>${cta()}`}
function privacy(){return `<article class="prose"><div class="eyebrow">Preview information</div><h1>Privacy & data</h1><p>This is a design preview of ZARBITZ. Live customer registration, identity verification, enquiry delivery, and private data storage have not been connected.</p><h2>Information entered here</h2><p>The enquiry form generates a downloadable draft on your device. It does not send the form to ZARBITZ. Workspace permissions are temporary demo state and reset on reload. Avoid entering sensitive information.</p><h2>Site resources</h2><p>Images are served with the site. Fonts may be requested from Google Fonts. Hosting and access to this private preview are provided by the hosting platform.</p><h2>Before customer launch</h2><p>A final privacy notice, terms, retention schedule, data licensing policy, and service contact details must be published once the company’s operating arrangements and providers are configured.</p><a class="button dark" href="#/contact">Prepare a project enquiry ↗</a></article>`}
let timers=[];function render(){timers.forEach(clearInterval);timers=[];const route=(location.hash.slice(1)||'/').split('?')[0];let html;if(route==='/')html=home();else if(route==='/solutions')html=`<section class="page-intro"><div class="eyebrow">Our solutions</div><h1>Intelligence for a<br>changing world.</h1><p>Explore satellite-based perspectives for agriculture, ground movement, and infrastructure.</p></section><section class="section" style="padding-top:0">${cards()}</section>${cta()}`;else if(route.startsWith('/solutions/')){const s=solutions.find(s=>route.endsWith('/'+s.slug));html=s?detail(s):'<section class="empty"><h1>Page not found</h1><a href="#/">Return home</a></section>'}else if(route==='/technology')html=technology();else if(route==='/contact')html=contact();else if(route==='/signin'||route==='/signup'){authMode=route.slice(1);html=auth()}else if(route==='/workspace')html=workspace();else if(route==='/about')html=about();else if(route==='/privacy')html=privacy();else html='<section class="empty"><h1>Page not found</h1><a href="#/">Return home</a></section>';$('#main').innerHTML=html;document.title='ZARBITZ — '+(route==='/'?'A clearer view. A better decision.':route.split('/').pop().replace(/-/g,' '));$('.menu-toggle').setAttribute('aria-expanded','false');if(route==='/contact'){const selected=new URLSearchParams(location.hash.split('?')[1]||'').get('solution');if(selected&&solutions.some(s=>s.slug===selected))$('#solution').value=selected;$('#contact-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target);download('ZARBITZ-enquiry-draft.txt','ZARBITZ PROJECT ENQUIRY — UNSENT DRAFT\n\n'+[...data].map(([k,v])=>k.toUpperCase()+': '+v).join('\n\n'),'text/plain');$('#form-result').textContent='Draft downloaded. No enquiry has been sent.'}}}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal()}
function updateStep(el,i){el.dataset.step=i;el.querySelector('.science-art').innerHTML=art(el.dataset.method,i)+'<span class="caption">CONCEPTUAL ILLUSTRATION · MOVEMENT EXAGGERATED</span>';el.querySelector('.animation-description').textContent=methods[el.dataset.method].text[i];el.querySelectorAll('[data-step]').forEach(b=>b.classList.toggle('active',Number(b.dataset.step)===i))}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.matches('.menu-toggle'))b.setAttribute('aria-expanded',b.getAttribute('aria-expanded')!=='true');if(b.matches('.close'))$('#modal').close();if(b.hasAttribute('data-step'))updateStep(b.closest('.explainer'),Number(b.dataset.step));if(b.hasAttribute('data-play')){const el=b.closest('.explainer');if(el._timer){clearInterval(el._timer);el._timer=null;el.classList.add('paused');b.textContent='Play ▷'}else{el.classList.remove('paused');updateStep(el,((Number(el.dataset.step)||0)+1)%3);el._timer=setInterval(()=>updateStep(el,((Number(el.dataset.step)||0)+1)%3),2600);timers.push(el._timer);b.textContent='Pause Ⅱ'}}if(b.dataset.auth){authType=b.dataset.auth;render()}if(b.dataset.info)modal(`<div class="eyebrow">Connection pending</div><h2>${b.dataset.info==='google'?'Google sign-in':b.dataset.info==='sso'?'Enterprise SSO':b.dataset.info==='phone'?'Phone verification':'Email sign-in'}</h2><p>This option will be enabled when ZARBITZ configures its identity provider. No credentials are collected in this preview.</p><a class="button dark" href="#/workspace" onclick="document.querySelector('#modal').close()">Explore demo workspace ↗</a>`);if(b.dataset.portal){portalTab=b.dataset.portal;if(location.hash!=='#/workspace')location.hash='/workspace';else render()}if(b.dataset.resource){const report=b.dataset.resource==='reports';if(!permissions[report?'report':'dataset']){$('#request-status').textContent='Demo access request recorded for this view. Explore the Admin tab to grant permission. No request was sent.'}else if(report)modal('<div class="eyebrow">Illustrative report · v1.2</div><h2>North Fields<br>Crop condition summary</h2><span class="badge">Synthetic data — not for decisions</span><p>Observation: 12 October 2026 · Publication: 16 October 2026</p><p>A synthetic vegetation indicator ranges from 0.42 to 0.78 across the example field. Variation identifies areas to inspect; it does not diagnose the cause.</p><p class="fine">Method: illustrative spectral index. No real satellite observations were processed for this example. Units: dimensionless. Quality: demonstration only.</p>');else download('zarbitz-synthetic-example.csv','demo_only,field_id,observation_date,vegetation_indicator,units\ntrue,DEMO-N01,2026-10-12,0.42,dimensionless\ntrue,DEMO-N02,2026-10-12,0.78,dimensionless\n','text/csv')}});
document.addEventListener('change',e=>{if(e.target.dataset.permission){permissions[e.target.dataset.permission]=e.target.checked;$('#permission-status').textContent='Demo permission updated. Open Reports or Datasets to see the result.'}});window.addEventListener('hashchange',()=>{render();scrollTo(0,0)});render();
